const rawOutput = items[0].json.output;
const cleanJsonString = rawOutput.replace(/```?json\n?|```|\njson\n?/g, '').trim();
const parsed = JSON.parse(cleanJsonString);

// ✅ Accede correctamente al body donde está call
const dataWebhook = $node["fin llamada"].json.body || {};
const toNumber = dataWebhook.call?.from_number || '';
const toNumberLimpio = toNumber.replace('+', '');

// Combina estado del coche
const estadoCocheObj = parsed.estado_coche || {};
const estado_coche = [
  estadoCocheObj.matricula,
  estadoCocheObj.kilometros,
  estadoCocheObj.estado
].filter(Boolean).join(', ');

// Devuelve salida final
return [
  {
    json: {
      telefono: toNumberLimpio,
      financiacion: parsed.financiacion,
      inmediates: parsed.inmediates,
      agendar_cita: parsed.agendar_cita,
      cita_fecha: parsed.cita_fecha,
      cita_hora: parsed.cita_hora,
      da_coche_en_pago: parsed.da_coche_en_pago,
      estado_coche: estado_coche,
      desea_notificaciones: parsed.desea_notificaciones,
      elaborar_perfil: parsed.elaborar_perfil
    }
  }
];
